// Renders every raster icon TransitVault ships, from one source (the favicon,
// web/src/app/icon.svg):
//
//   web/public/icons/icon-{192,512}.png       PWA "any" icons (rounded tile, as the favicon)
//   web/public/icons/maskable-{192,512}.png   PWA maskable icons (full bleed, art in the safe zone)
//   infra/play-store/graphics/icon-512.png    Play hi-res icon (full bleed, opaque; Play masks it)
//   infra/play-store/graphics/feature-graphic.png  1024 x 500 Play feature graphic
//
// The Android launcher icons in android/ are generated by Bubblewrap from the
// 512 PWA icons, so rerun this, redeploy the web app, and regenerate android/
// if the artwork changes.
//
//   cd infra/play-store/tools && npm install && npm run graphics
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const SVG = readFileSync(here("../../../web/src/app/icon.svg"), "utf8");
const WEB_ICONS = here("../../../web/public/icons/");
const PLAY = here("../graphics/");
mkdirSync(WEB_ICONS, { recursive: true });
mkdirSync(PLAY, { recursive: true });

// Full-bleed variant: square background, artwork shrunk into the centre so it
// survives a circular mask (safe zone = 80% diameter circle).
function fullBleed(artScale) {
  const off = (1024 * (1 - artScale)) / 2;
  return SVG.replace('<rect width="1024" height="1024" rx="224" fill="url(#bg)"/>', '<rect width="1024" height="1024" fill="url(#bg)"/>')
    .replace(/(<path d="M512 170[\s\S]*<\/svg>)/, (m) => `<g transform="translate(${off} ${off}) scale(${artScale})">${m.replace("</svg>", "")}</g></svg>`);
}

const page = (size, svg) => `<!doctype html><html><head><style>html,body{margin:0;background:transparent}
  svg{display:block;width:${size}px;height:${size}px}</style></head><body>${svg}</body></html>`;

const FEATURE = `<!doctype html><html><head>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@500;700;800&display=swap" rel="stylesheet">
<style>
  html,body{margin:0}
  .f{width:1024px;height:500px;position:relative;overflow:hidden;font-family:Geist,sans-serif;
     background:radial-gradient(60% 80% at 0% 0%, #dbeafe 0%, transparent 70%),
                radial-gradient(55% 75% at 100% 100%, #fde68a 0%, transparent 70%),#fafafa;
     display:flex;align-items:center;gap:56px;padding:0 72px;box-sizing:border-box}
  .icon{flex:none;width:250px;height:250px;filter:drop-shadow(0 24px 32px rgba(18,21,28,.35))}
  .icon svg{width:250px;height:250px}
  h1{margin:0;font-size:80px;font-weight:800;letter-spacing:-2px;color:#18181b}
  p{margin:14px 0 0;font-size:34px;font-weight:500;line-height:1.25;color:#3f3f46}
  p b{color:#1d4ed8;font-weight:700}
  small{display:block;margin-top:22px;font:500 20px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:3px;color:#71717a}
</style></head><body><div class="f">
  <div class="icon">${SVG}</div>
  <div><h1>TransitVault</h1><p>Parent flying alone?<br><b>Find someone on the same flight.</b></p><small>BY 3PANDALABS</small></div>
</div></body></html>`;

const jobs = [
  { out: WEB_ICONS + "icon-192.png", size: 192, html: page(192, SVG) },
  { out: WEB_ICONS + "icon-512.png", size: 512, html: page(512, SVG) },
  { out: WEB_ICONS + "maskable-192.png", size: 192, html: page(192, fullBleed(0.78)) },
  { out: WEB_ICONS + "maskable-512.png", size: 512, html: page(512, fullBleed(0.78)) },
  // Play rejects alpha; Play rounds the corners itself.
  { out: PLAY + "icon-512.png", size: 512, html: page(512, fullBleed(0.9)), opaque: true },
  { out: PLAY + "feature-graphic.png", w: 1024, h: 500, html: FEATURE, opaque: true },
];

const browser = await chromium.launch();
for (const j of jobs) {
  const w = j.w ?? j.size;
  const h = j.h ?? j.size;
  const p = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  await p.setContent(j.html, { waitUntil: "networkidle" });
  await p.evaluate(() => document.fonts.ready);
  await p.screenshot({ path: j.out, omitBackground: !j.opaque, clip: { x: 0, y: 0, width: w, height: h } });
  await p.close();
  console.log(`${w}x${h}  ${j.out}`);
}
await browser.close();
